+instruct storeL_immI0(memorylong mem, immI0 zero, iRegI temp) %{
+  predicate(!((StoreLNode*)n)->require_atomic_access());
+  match(Set mem (StoreL mem zero));
+  effect(TEMP temp);
+  ins_cost(MEMORY_REF_COST + DEFAULT_COST);
+
+  size(12);
+  format %{ "MOV    $temp,0\n\t"
+            "STR    $temp,$mem\t! long zero\n\t"
+            "STR    $temp,$mem+4" %}
+
+  ins_encode %{
+    __ mov($temp$$Register, 0);
+    Address Amemlo = Address::make_raw($mem$$base, $mem$$index, $mem$$scale, $mem$$disp, relocInfo::none);
+    Address Amemhi = Address::make_raw($mem$$base, $mem$$index, $mem$$scale, $mem$$disp + 4, relocInfo::none);
+    __ str($temp$$Register, Amemlo);
+    __ str($temp$$Register, Amemhi);
+  %}
+  ins_pipe(istore_mem_reg);
+%}
+

